class Solution {
public:
    vector<string> buildArray(vector<int>& target, int n) {
        vector<string> ops;
        int t = 0;
        for (int x = 1; x <= n && t < (int)target.size(); x++) {
            ops.push_back("Push");
            if (target[t] == x) t++;
            else ops.push_back("Pop");
        }
        return ops;
    }
};
